def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    recent = history[-15:] if n >= 15 else history
    opp_defs = 0
    for _, o in recent:
        if o == 'D':
            opp_defs += 1
    if opp_defs >= 5:
        return 'D'
    return 'C'
